<?php require __DIR__.'/app/bootstrap.php';if(!empty($_SESSION['admin_id'])){header('Location: /admin.php');exit;}$err='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$q=db()->prepare('SELECT * FROM admins WHERE username=?');$q->execute([trim($_POST['username']??'')]);$a=$q->fetch();if($a&&password_verify($_POST['password']??'',$a['password_hash'])){session_regenerate_id(true);$_SESSION['admin_id']=$a['id'];$_SESSION['admin_name']=$a['username'];header('Location: /admin.php');exit;}$err='Invalid username or password.';}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin login</title><link rel="stylesheet" href="/assets/style.css"></head><body class="auth"><form class="panel authbox" method="post"><h1>Admin login</h1><?php if($err):?><p class="error"><?=e($err)?></p><?php endif?><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><label>Username<input name="username" required></label><label>Password<input type="password" name="password" required></label><button>Sign in</button></form></body></html>